import { useState } from "react";
import "./Sidebar.css";
import Cadastro from "../cadastro/Cadastro";

export default function Sidebar() {
  const [isOpen, setIsOpen] = useState(false);

const [showCadastro, setShowCadastro] = useState(false);

return (
	<div className={`sidebar ${isOpen ? "open" : "closed"}`}>
		<div>
			<button className="toggle-btn" onClick={() => setIsOpen(!isOpen)}>
				☰
			</button>

			<ul className="menu">
				<li>
					{isOpen && (
						<span className="text">
							<a
								className="sidebar-a"
								href="#"
								onClick={() => setShowCadastro((prev) => !prev)}
							>
								Cadastrar
							</a>
						</span>
					)}
				</li>

				<li>
					{isOpen && <span className="text">Mapa</span>}
				</li>

				<li>
					{isOpen && <span className="text">Configurações</span>}
				</li>
			</ul>
		</div>
		<div>
			{isOpen && showCadastro && <SearchControl />}
		</div>
	</div>
);
}
